jedi.inference.names._merge_name_docs:
def _merge_name_docs(names):
    doc = ''
    for name in names:
        if doc:
            doc += '\n' + '-' * 30 + '\n'
        doc += name.py__doc__()
    return doc

jedi.api.helpers._get_index_and_key:
def _get_index_and_key(nodes, position):
    """
    Returns the amount of commas and the keyword argument string.
    """
    nodes_before = [c for c in nodes if c.start_pos < position]
    if nodes_before[-1].type == 'arglist':
        return _get_index_and_key(nodes_before[-1].children, position)
    key_str = None
    last = nodes_before[-1]
    if (last.type == 'argument' and last.children[1] == '=' and last.children[1].end_pos <= position):
        key_str = last.children[0].value
    elif last == '=':
        key_str = nodes_before[-2].value
    return (nodes_before.count(','), key_str)

jedi.api.helpers.filter_follow_imports:
def filter_follow_imports(names, follow_builtin_imports=False):
    for name in names:
        if name.is_import():
            new_names = list(filter_follow_imports(name.goto(), follow_builtin_imports=follow_builtin_imports))
            found_builtin = False
            if follow_builtin_imports:
                for new_name in new_names:
                    if new_name.start_pos is None:
                        found_builtin = True
            if found_builtin:
                yield name
            else:
                yield from new_names
        else:
            yield name

jedi.api.helpers.split_search_string:
def split_search_string(name):
    (type, _, dotted_names) = name.rpartition(' ')
    if type == 'def':
        type = 'function'
    return (type, dotted_names.split('.'))

jedi.inference.arguments.try_iter_conten:
def try_iter_content(types, depth=0):
    """Helper method for static analysis."""
    if depth > 10:
        return
    for typ in types:
        try:
            f = typ.py__iter__
        except AttributeError:
            pass
        else:
            for lazy_value in f():
                try_iter_content(lazy_value.infer(), depth + 1)

parso.python.diff._func_or_class_has_sui:
def _func_or_class_has_suite(node):
    if node.type == 'decorated':
        node = node.children[-1]
    if node.type in ('async_funcdef', 'async_stmt'):
        node = node.children[-1]
    return (node.type in ('classdef', 'funcdef') and node.children[-1].type == 'suite')

jedi.inference.gradual.generics._resolve:
def _resolve_forward_references(context, value_set):
    for value in value_set:
        if is_string(value):
            from jedi.inference.gradual.annotation import _get_forward_reference_node
            node = _get_forward_reference_node(context, value.get_safe_value())
            if node is not None:
                for c in context.infer_node(node):
                    yield c
        else:
            yield value
